def maxHeapify(i, heapSize):
    l = left(i)
    r = right(i)
    largest = i
    if l <= heapSize and value(l) > value(largest):
        largest = l
    if r <= heapSize and value(r) > value(largest):
        largest = r
    if largest != i:
        swap(i, largest)
        maxHeapify(largest, heapSize)

